import {trainModel,predictModel,evaluate,exportFit} from '../agent/models.mjs';
import {regressionMetrics,classificationMetrics,finite} from '../agent/core.mjs';
import {trainTrees,predictTrees,trainIsolation,isolationScores,avg} from './engine.mjs';
export const lagKeys=['lag_oil','lag_water','lag_pressure','lag_injection','lag_water_cut'];
const baseKeys=['oil','water','pressure','injection','water_cut'];
export function nextDay(rows,context=[]){const groups={};for(const r of [...context,...rows]){(groups[r.well_id]??=[]).push(r);}const identities=new Set(rows.map(r=>r.well_id+'@'+r.date)),out=[];for(const rs0 of Object.values(groups)){const rs=[...new Map(rs0.map(r=>[r.date,r])).values()].sort((a,b)=>a.date.localeCompare(b.date));for(let i=1;i<rs.length;i++){if(Date.parse(rs[i].date)-Date.parse(rs[i-1].date)!==86400000||!identities.has(rs[i].well_id+'@'+rs[i].date))continue;out.push({...rs[i],...Object.fromEntries(baseKeys.map((k,j)=>[lagKeys[j],Number(rs[i-1][k])]))});}}return out;}
function windows(rows,scale){const grouped={};for(const r of rows)(grouped[r.well_id]??=[]).push(r);const xs=[],ys=[],records=[];for(const rs0 of Object.values(grouped)){const rs=[...rs0].sort((a,b)=>a.date.localeCompare(b.date));for(let i=8;i<rs.length;i++){if(Date.parse(rs[i].date)-Date.parse(rs[i-8].date)!==8*86400000)continue;const v=rs.slice(i-8,i).map(r=>baseKeys.map((k,j)=>(r[k]-scale[j].m)/scale[j].s));if(v.flat().some(x=>!Number.isFinite(x)))throw Error('序列含缺失或非数值特征');xs.push(v);ys.push([(rs[i].oil-scale[0].m)/scale[0].s]);records.push(rs[i]);}}return {xs,ys,records};}
export async function train(m,rows,val,options,progress,remote){if(m.mode==='shared')return trainModel(m.id,rows,val,options,progress);if(m.mode==='remote')return remoteTrain(m,rows,val,options,remote);const start=performance.now();let fit;
 if(['tree','profile','effect'].includes(m.mode)){const data=m.mode==='tree'?nextDay(rows):rows,keys=m.mode==='tree'?lagKeys:m.required.filter(k=>k!==m.target);fit=trainTrees(m.id==='boost'?'boost':'forest',data,keys,m.target,options);fit.modelId=m.id;fit.mode=m.mode;}
 else if(m.mode==='isolation')fit=trainIsolation(rows,m.required,options);
 else if(m.mode==='lstm'){const tf=globalThis.tf;if(!tf)throw Error('TensorFlow训练引擎尚未加载');await tf.ready();const scale=baseKeys.map(k=>{const m=avg(rows.map(r=>r[k]));return {m,s:Math.sqrt(avg(rows.map(r=>(r[k]-m)**2)))||1};}),tr=windows(rows,scale),va=windows(val,scale);if(tr.xs.length<24)throw Error('至少需要24个连续8天历史窗口');const network=tf.sequential();network.add(tf.layers.lstm({inputShape:[8,5],units:16}));network.add(tf.layers.dense({units:8,activation:'relu'}));network.add(tf.layers.dense({units:1}));network.compile({optimizer:tf.train.adam(.003),loss:'meanSquaredError'});const x=tf.tensor3d(tr.xs),y=tf.tensor2d(tr.ys),vx=va.xs.length?tf.tensor3d(va.xs):null,vy=va.ys.length?tf.tensor2d(va.ys):null,history=[];try{await network.fit(x,y,{epochs:options.epochs??10,batchSize:32,shuffle:false,validationData:vx?[vx,vy]:undefined,callbacks:{onEpochEnd:(e,logs)=>{history.push({epoch:e+1,...logs});progress((e+1)/(options.epochs??10),logs);}}});fit={id:m.id,network,scale,history,trainedRows:rows.length,target:'oil',mode:'lstm'};}catch(e){network.dispose();throw e;}finally{x.dispose();y.dispose();vx?.dispose();vy?.dispose();}}
 else throw Error('未知训练模式');return {...fit,duration:(performance.now()-start)/1000};}
export async function predict(m,fit,rows,context=[],remote){if(m.mode==='shared')return predictModel(fit,rows);if(m.mode==='remote'){const d=nextDay(rows,context);if(!d.length)throw Error('需至少2条连续日生产数据');const response=await api(remote,'/predict',{model_token:fit.model_token,rows:d});return d.map((row,i)=>({...row,actual:row.oil,prediction:response.predictions[i]}));}
 if(m.mode==='lstm'){const tf=globalThis.tf,w=windows([...context,...rows],fit.scale),ids=new Set(rows.map(r=>r.well_id+'@'+r.date));if(!w.xs.length)throw Error('无连续8天历史窗口');const x=tf.tensor3d(w.xs),y=fit.network.predict(x);try{const a=await y.data();return w.records.map((r,i)=>({...r,actual:r.oil,prediction:a[i]*fit.scale[0].s+fit.scale[0].m})).filter(r=>ids.has(r.well_id+'@'+r.date));}finally{x.dispose();y.dispose();}}
 if(m.mode==='isolation'){const s=isolationScores(fit,rows);return rows.map((r,i)=>({...r,actual:r.label,score:s[i],prediction:s[i]>fit.threshold?1:0}));}
 const data=m.mode==='tree'?nextDay(rows,context):rows,values=predictTrees(fit,data);return data.map((r,i)=>({...r,actual:r[m.target],prediction:values[i]}));}
export function metrics(m,fit,rows){if(m.mode==='shared')return evaluate(fit,rows);if(m.mode==='isolation'){const a=rows.filter(r=>finite(r.actual)&&[0,1].includes(Number(r.actual)));return a.length?classificationMetrics(a.map(r=>Number(r.actual)),a.map(r=>r.prediction)):null;}return regressionMetrics(rows.map(r=>r.actual),rows.map(r=>r.prediction));}
export async function serialize(m,fit){if(fit.network){if(m.mode==='shared')return exportFit(fit);const a={...fit};delete a.network;await fit.network.save({save:async r=>{a.modelTopology=r.modelTopology;a.weightSpecs=r.weightSpecs;a.weightData=Array.from(new Uint8Array(r.weightData));return {modelArtifactsInfo:{dateSaved:new Date(),modelTopologyType:'JSON'}};}});return a;}return {...fit,trainRows:undefined};}
export async function api(remote,path,body){if(!remote?.url||!remote?.token)throw Error('请先在大模型与服务页配置服务地址及访问令牌');const u=new URL(remote.url);if(u.protocol!=='https:'&&!['localhost','127.0.0.1'].includes(u.hostname))throw Error('远程计算服务必须使用HTTPS');const c=new AbortController(),timeout=setTimeout(()=>c.abort(),120000);try{const res=await fetch(remote.url.replace(/\/$/,'')+path,{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+remote.token},body:JSON.stringify(body),signal:c.signal});const data=await res.json();if(!res.ok)throw Error(data.detail??data.error??'服务请求失败');return data;}finally{clearTimeout(timeout);}}
async function remoteTrain(m,rows,val,options,remote){return {...await api(remote,'/train',{model_id:m.id,rows:nextDay(rows),validation:nextDay(val,rows),options}),id:m.id,history:[],trainedRows:rows.length};}
